import { cacheTag } from 'next/cache';

export type Post = {
  id: string;
  title: string;
  content: string;
  createdAt: Date;
};

// In-memory store for demo (resets on server restart)
const posts: Post[] = [];

export async function getPosts(): Promise<Post[]> {
  'use cache';
  cacheTag('posts');

  return [...posts].sort(
    (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  );
}

export function createPostInStore(title: string, content: string): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: new Date(),
  };
  posts.push(post);
  return post;
}

